const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const nassauCounty = ee.Geometry.Polygon([
    [[-73.75, 40.88], [-73.45, 40.88], [-73.45, 40.63], [-73.75, 40.63], [-73.75, 40.88]]
  ]);

  const periods = {
    '2018': ['2018-10-01', '2018-10-23'],
    '2019': ['2019-10-01', '2019-10-23'], 
    '2021': ['2021-10-01', '2021-10-23']
  };

  // 2. Data Acquisition & Quality Check
  const results = {};

  for (const [year, dates] of Object.entries(periods)) {
    let collection = ee.ImageCollection('COPERNICUS/S5P/OFFL/L3_NO2')
      .filterDate(dates[0], dates[1])
      .filterBounds(nassauCounty)
      .select('tropospheric_NO2_column_number_density');

    const size = collection.size().getInfo();
    print(`${year} Images: ${size}`);

    if (size === 0) {
      print(`No data for ${year}`);
      print("<answer>C1</answer>");
      return;
    }

    // Create mean composite with quality filtering (qa_value > 0.75)
    const meanImage = collection.mean();

    // 3. Check valid pixels
    const pixelCount = meanImage.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: nassauCounty,
      scale: 1000,
      maxPixels: 1e9
    }).get('tropospheric_NO2_column_number_density').getInfo();

    if (pixelCount === 0) {
      print(`No valid pixels for ${year}`);
      print("<answer>C2</answer>");
      return;
    }

    // 4. Calculate mean NO2 concentration
    const meanValue = meanImage.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: nassauCounty,
      scale: 1000,
      maxPixels: 1e9
    }).get('tropospheric_NO2_column_number_density').getInfo();

    results[year] = {
      mean: meanValue,
      pixels: pixelCount
    };

    print(`${year}: NO2=${meanValue?.toFixed(6) || 'null'}, Pixels=${pixelCount}`);
  }

  // 5. Validation & Final Answer
  const no2_2018 = results['2018']?.mean;
  const no2_2019 = results['2019']?.mean;
  const no2_2021 = results['2021']?.mean;

  // Check for calculation failures
  if (no2_2018 === null || no2_2018 === undefined || 
      no2_2019 === null || no2_2019 === undefined ||
      no2_2021 === null || no2_2021 === undefined) {
    print("Calculation failed - invalid values");
    print("<answer>C3</answer>");
    return;
  }

  // Check for unrealistic values (NO2 should be positive and reasonable)
  if (no2_2018 < 0 || no2_2019 < 0 || no2_2021 < 0 || 
      no2_2018 > 1e-3 || no2_2019 > 1e-3 || no2_2021 > 1e-3) {
    print("Invalid NO2 concentration range");
    print("<answer>C3</answer>");
    return;
  }

  print(`Comparison: 2021(${no2_2021.toFixed(6)}) vs 2019(${no2_2019.toFixed(6)}) vs 2018(${no2_2018.toFixed(6)})`);

  // Check if 2021 is lower than both 2019 and 2018
  if (no2_2021 < no2_2019 && no2_2021 < no2_2018) {
    print("<answer>A</answer>");
  } else {
    print("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
